import json,copy
from pathlib import Path
S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));out={}
n={'購買時機':'收購時間內會繼續等可買價；只在第一次進場若首個非開高低同價的有效日最低價仍高於上限就放棄此債。','最高收購價格':'日最低價<=上限才買，成交為min(當日開盤,此價格)，包含等於門檻。','停利價格':'買入後另一日最高價>=此價格出場，成交為max(當日開盤,此價格)。','最多進場次數':'每張可轉債建立一輪買賣的次數上限；每次只留一組持倉，獲利退出後後續日期才可再進。以整數計數對decimal門檻比較。','買入價格':'空手且仍在收購區間，最低價<=此價格買入，成交為min(當日開盤,門檻)。','賣出價格':'持倉日最高價>=此固定賣價賣出，成交為max(當日開盤,門檻)。','停利點數':'此輪實際買入價加此點數為賣出目標；最高價>=目標時以max(開盤,目標)賣，不是報酬率。','資金基數':'單債每次投入的萬元基數；有擔保或L1信評再乘有擔乘數，經槓桿公式換為整張數，不是整個組合共享現金池。','有擔利率':'有擔保或信評L1採用此年率數值；與預計持有年數相乘加入每張初始自付成本，最後另依實際日數/365計融資費。','無擔利率':'不具擔保且非L1採用此年率，初始槓桿成本按預計年數計，實現損益按實際持有年數扣。','有擔乘數':'有擔保或L1的初始資金基數倍數，其他債固定一倍；XCombo加碼部位不乘此數。','預計持有':'初始槓桿的年數估計：每張成本=max(買價−100,0)+利率×此年數；不是到期強制平倉日期。','加碼資金基數':'每次加碼以此萬元金額換算槓桿張數，不乘有擔乘數，也不檢查組合可用現金。','加碼預計持有':'加碼批次的成本使用max(買價−100,0)+利率×此年數；不改變原始批次成本，也不作定時出場。','加碼點數':'最近仍持有批次的買入價再減此點數為下一加碼門檻；最低價到價時買，最多每天一批。','最多加碼次數':'同時仍持有的加碼批次上限，不含原始一批；加碼停利移出後會釋放名額，可再買，不是終身累積加碼次數。'}
data='讀取每張可轉債完整日OHLC資料，排除開盤為0列；曾有成交後的零量日沿用前日收盤。全域提前N日結算會裁掉最後N筆，並非按策略結算時間預先裁資料。'
period='收購開始、收購結束、結算時間由執行環境提供，須開始<結束<結算；收購邊界含當日，結束後僅管理持倉。'
plain='每張可轉債一張做多，損益按賣買價差計，持有期間以每日收盤估值；此路徑沒有額外滑價、手續費或槓桿利息扣除。'
xcapital='每張初始自付成本=max(買價−100,0)+年利率×預計年數，槓桿=100/成本，張數截為整數(資金萬元×槓桿/10)；擔保Y或信評L1算有擔，初始資金再乘有擔乘數。'
xprofit='槓桿部位實現損益=(賣價−買價−年利率×實際持有年數)×張數；日內未實現曲線用(收盤−100−預付成本)×張數，成本含預估全年期費用，因此與按日應計利息不同。'
xcaveat='不檢查全組合現金上限，買價和利率／預計期間組合若使成本為0會除以0；資金不足整張會得到0張但仍保留交易紀錄。未另扣滑價與手續費。'
for name in ['BHS','BLSH','BLSH2','XBHS','XBLSH','XBLSH2','XCombo']:
 lever=name.startswith('X');hold=name in ['BHS','XBHS'];combo=name=='XCombo';relative=name.endswith('2');iid='SuperCB/Stg'+name
 a={'family':'可轉債收購','summary':'','entry':[],'exit':[],'mechanics':[period,data], 'caveats':[], 'parameterNotes':{p['name']:n[p['name']] for p in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
 if hold:
  a['summary']=('一次收購可轉債，達固定價提前停利，否則按有效資料最後收盤退出。' if lever else '一次收購可轉債，達固定價提前停利，否則持至結算附近。')+('依有擔／無擔利率與預估持有年數計槓桿部位。' if lever else '每債固定一張。')
  a['entry']=['收購區間由早往晚找第一個開盤、最高、最低並非全部相同的交易日；最低價<=最高收購價格才買，成交取開盤與上限較低者。','若購買時機為只在第一次進場，第一個非同價日仍高於上限就整債放棄；被同價過濾的日不消耗此第一次機會。每債最多一輪。']
  a['exit']=['自買入翌筆起，到結算日內以日最高價檢查固定停利價；若到價，取開盤與停利價較高者賣出。']
  if lever:a['exit'].append('未停利直接用裁尾後整份資料最後一筆收盤退出，並未取策略結算日以前的最後一筆；出場可以晚於結算時間。')
  else:a['exit'].append('未停利採結算日以前最後一筆的收盤，沒有後續符合日期的資料時沿用買入日收盤；不直接使用第一筆超過結算日的價格。')
  a['caveats']=['沒有停損，也不允許買入當日直接停利；當日OHLC同價過濾不等於實際可成交量或漲跌停驗證。']
 else:
  a['summary']=('可轉債低買後永久保留原始部位，有擔債下跌時分批加碼，反彈只賣出加碼批次。' if combo else '可轉債跌到指定價格買入，'+('以每輪實際買價加點數停利' if relative else '漲到固定價格停利')+'，在次數與收購區間內反覆做多。')+('各批次另計槓桿與持有利息。' if lever else '每輪固定一張。')
  a['entry']=['空手且在收購區間內，日最低價<=買入價格時以min(開盤,買入價格)進場；第一次買入前開高低全相同的日跳過。']
  if combo:
   a['entry'].append('只對有擔或L1債加碼：最低價觸及最後仍持有批次買價−加碼點數時再買一批，成交取開盤與門檻較低者。每天最多一批，加碼優先且該日不再檢查各批停利。')
   a['exit']=['原始第一批不作價格停利；持有第二批起，逐批以該批買價+停利點數檢查日最高價，到價取開盤與目標較高者賣出，可同日賣多批。','超過結算日即退回前一有效資料列，未退出的所有批次用該列收盤平倉；資料先結束則用資料最後收盤。']
   a['caveats']=['加碼批次賣出會釋放名額，最多加碼次數限制同時持有批次，不限制全期累積買入；收購結束只擋初始進場，已持有後仍可加碼到結算。','沒有停損；日內先加碼後continue，當日高點即使也到停利門檻不會賣。初始買入當日不加碼也不停利。']
   a['parameterNotes']['停利點數']='每個加碼批次的實際買價加此點數為目標；原始第一批不依此停利。'
  else:
   a['entry'].append('每債同時一輪，進場計數未達最多進場次數才能再買；第二輪起不再過濾開高低全同價的日。平倉後最快下一筆日期重新檢查。')
   a['exit']=['從買入下一筆開始，日最高價>='+('此輪實際買價+停利點數' if relative else '固定賣出價格')+'則以max(當日開盤,目標)賣出。','過結算時間則退到前一根收盤，仍有倉時全部退出；若資料先結束則用末筆收盤。進場或出場後當日都不再進另一輪。']
   a['caveats']=['沒有停損；日OHLC到價即假定成交，沒有盤中路徑與可成交量檢查。最多進場次數為decimal而計數為整數，正小數門檻可能容許進到下一整數次。']
 a['mechanics'].append(xcapital if lever else plain)
 if lever:a['mechanics'].append(xprofit);a['caveats'].append(xcaveat)
 out[iid]=a
(S/'analysis/SuperCB.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
p=S/'programs.json';v=json.loads(p.read_text(encoding='utf8'));v['SuperCB']='可轉債日資料收購：單次持有、反覆低買高賣、買價加點數停利，以及有擔保債下跌加碼的複合策略。X版本加入有擔／無擔利息、預計持有與整張槓桿換算；BHS與XBHS未停利的實際出場日期不同。';p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote 7 SuperCB explanations')
